{
  "instrument": "Directive (EU) 2023/2673",
  "jurisdiction": "EU",
  "summary": "Offer a clearly labelled, two-step withdrawal function on your online shop and confirm each withdrawal on a durable medium, for contracts concluded from 19 June 2026. Directive (EU) 2023/2673 inserts Article 11a into the Consumer Rights Directive for traders that conclude contracts through an online interface.",
  "effective_dates": [
    "2026-06-19"
  ],
  "obligations": [
    {
      "text": "Provide a withdrawal function on the online interface.",
      "quote": "the trader shall ensure that the consumer can also exercise the right of withdrawal by means of a withdrawal function"
    },
    {
      "text": "Label it clearly and make it two-step (fill in, then confirm).",
      "quote": "The withdrawal function shall be labelled with the words 'withdraw contract here' or a corresponding unambiguous formulation in an easily legible manner"
    },
    {
      "text": "Keep the withdrawal function available throughout the withdrawal period.",
      "quote": "The withdrawal function shall be continuously available during the withdrawal period."
    },
    {
      "text": "Send an acknowledgement on a durable medium.",
      "quote": "the trader shall communicate to the consumer without undue delay an acknowledgement of receipt of the withdrawal on a durable medium"
    }
  ]
}
